package com.danieldk.splatevpn.ui.theme

internal val AppStrings.connectionTools get() = ConnectionToolsStrings(this)

internal class ConnectionToolsStrings(private val strings: AppStrings) {
    val balancerSettings get() = strings.localized("Настройки балансировщика", "Balancer settings")
    val balanced get() = strings.localized("Автоматический · по умолчанию", "Automatic · default")
    val balancedHint get() = strings.localized("Выбирает сервер при подключении, заменяет недоступный и ищет более быстрый при ухудшении связи.", "Selects a server on connect, replaces failed nodes and looks for a faster one when quality drops.")
    val failover get() = strings.localized("Только при сбое", "On failure only")
    val failoverHint get() = strings.localized("Сохраняет рабочий сервер. Переключается, только когда несколько проверок подряд подтвердили сбой.", "Keeps a working server. Switches only after consecutive checks confirm a failure.")
    val initial get() = strings.localized("Только при подключении", "On connect only")
    val initialHint get() = strings.localized("Один раз выбирает сервер при подключении. Во время сеанса не переключает, даже если сервер перестал отвечать.", "Selects a server once on connect. Never switches during the session, even if that server stops responding.")
    val healthInterval get() = strings.localized("Интервал проверки связи", "Connection check interval")
    val failureCount get() = strings.localized("Неудачных проверок до смены", "Failed checks before switching")
    val optimizationInterval get() = strings.localized("Плановый поиск лучшего сервера", "Scheduled search for a better server")
    val cooldown get() = strings.localized("Пауза между улучшениями", "Pause between improvements")
    val improvement get() = strings.localized("Минимальный выигрыш по задержке", "Minimum latency improvement")
    val reset get() = strings.localized("Вернуть настройки по умолчанию", "Restore default settings")
    fun seconds(value: Int) = String.format(strings.localized("%d с", "%d s"), value)
    fun minutes(value: Int) = String.format(strings.localized("%d мин", "%d min"), value)
    val disabledHint get() = strings.localized("Параметры применятся, когда включён автовыбор сервера.", "These options apply while auto-select is enabled.")
    val speedMethod get() = strings.localized("Загрузка через VPN · 2 потока · 10 с · до 128 МБ", "VPN download · 2 streams · 10 s · up to 128 MB")
    val speedStart get() = strings.localized("Начать тест скорости", "Start speed test")
    val speedStop get() = strings.localized("Остановить тест", "Stop speed test")
    val vpnRequired get() = strings.localized("Сначала подключите VPN", "Connect the VPN first")
    val vpnChanged get() = strings.localized("Соединение изменилось. Запустите тест заново.", "The connection changed. Run the test again.")
    val timeout get() = strings.localized("Сервер теста не ответил вовремя", "The test server timed out")
    val dns get() = strings.localized("Не удалось определить адрес сервера", "Could not resolve the test server")
    val network get() = strings.localized("Сервер теста недоступен. Попробуйте другой VPN-узел.", "Test server unavailable. Try another VPN node.")
    val invalidSample get() = strings.localized("Недостаточно данных для достоверного замера", "Not enough data for a reliable measurement")
    val sampleDetails get() = strings.localized("%.1f МБ · %.1f с измерения", "%.1f MB · %.1f s measured")
    val megabytesPerSecond get() = strings.localized("МБ/с", "MB/s")
    val megabytes get() = strings.localized("МБ", "MB")
